struct Counter {
    count: u32,
    max: u32,
}

impl Counter {
    fn new(max: u32) -> Self {
        Counter { count: 0, max }
    }
    fn increment(&mut self) {
        if self.count < self.max {
            self.count += 1;
        }
    }
    fn value(&self) -> u32 {
        self.count
    }
    fn is_maxed(&self) -> bool {
        self.count >= self.max
    }
}

trait Shape {
    fn area(&self) -> f64;
    fn perimeter(&self) -> f64;
}

struct Circle { radius: f64 }
struct Rectangle { width: f64, height: f64 }

impl Shape for Circle {
    fn area(&self) -> f64 { std::f64::consts::PI * self.radius * self.radius }
    fn perimeter(&self) -> f64 { 2.0 * std::f64::consts::PI * self.radius }
}

impl Shape for Rectangle {
    fn area(&self) -> f64 { self.width * self.height }
    fn perimeter(&self) -> f64 { 2.0 * (self.width + self.height) }
}

#[derive(Debug)]
enum AppError {
    NotFound(String),
    InvalidInput(String),
    Io(std::io::Error),
}

impl From<std::io::Error> for AppError {
    fn from(e: std::io::Error) -> Self { AppError::Io(e) }
}

fn read_config(path: &str) -> Result<String, AppError> {
    let content = std::fs::read_to_string(path)?;
    if content.is_empty() {
        return Err(AppError::InvalidInput("empty config".to_string()));
    }
    Ok(content)
}

enum Command {
    Quit,
    Echo(String),
    Move { x: i32, y: i32 },
    Color(u8, u8, u8),
}

fn execute(cmd: Command) -> String {
    match cmd {
        Command::Quit => "Goodbye".to_string(),
        Command::Echo(msg) => msg,
        Command::Move { x, y } => format!("Moving to ({}, {})", x, y),
        Command::Color(r, g, b) => format!("#{:02x}{:02x}{:02x}", r, g, b),
    }
}

fn process_names(names: &[&str]) -> Vec<String> {
    names.iter()
        .filter(|name| name.len() > 3)
        .map(|name| name.to_uppercase())
        .collect()
}

fn sum_even_squares(nums: &[i32]) -> i32 {
    nums.iter()
        .filter(|&&n| n % 2 == 0)
        .map(|&n| n * n)
        .sum()
}

enum Tree<T> {
    Leaf(T),
    Branch {
        value: T,
        left: Box<Tree<T>>,
        right: Box<Tree<T>>,
    },
}

impl<T: std::fmt::Display> Tree<T> {
    fn depth(&self) -> usize {
        match self {
            Tree::Leaf(_) => 1,
            Tree::Branch { left, right, .. } => {
                1 + left.depth().max(right.depth())
            }
        }
    }
}

fn find_user(id: u32) -> Option<String> {
    if id > 0 { Some(format!("User_{}", id)) } else { None }
}

fn greet(id: u32) -> String {
    find_user(id)
        .map(|name| format!("Hello, {}!", name))
        .unwrap_or_else(|| "User not found".to_string())
}

fn first_even(nums: &[i32]) -> Option<i32> {
    nums.iter().find(|&&n| n % 2 == 0).copied()
}

fn apply_twice<T: Copy, F: Fn(T) -> T>(f: F, val: T) -> T {
    f(f(val))
}

fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n
}

fn main() {
    let double = |x: i32| x * 2;
    println!("{}", apply_twice(double, 3)); // 12
    let add5 = make_adder(5);
    println!("{}", add5(10)); // 15
}

